-- GENERATED by tests/bench/edit/make_old_impl.py from commit 971e8cb.  The original implementations, schema mc_old, for A/B timing and equivalence tests.
create schema if not exists mc_old;

create or replace function mc_old.set_blocks(p_dim text, xs int[], ys int[], zs int[], blocks text[]) returns int language plpgsql volatile as $$
declare
    g     record;
    total int := 0;
begin
    if cardinality(xs) <> cardinality(ys) or cardinality(xs) <> cardinality(zs) or cardinality(xs) <> cardinality(blocks) then
        raise exception 'set_blocks: the four arrays must have the same length';
    end if;
    -- sorted by section so concurrent batches lock in the same order
    for g in
        select t.x >> 4 as cx, t.y >> 4 as sy, t.z >> 4 as cz,
               array_agg(mc.section_idx(t.x, t.y, t.z) order by t.o) as idxs, array_agg(t.b order by t.o) as names
          from unnest(xs, ys, zs, blocks) with ordinality t(x, y, z, b, o)
         group by 1, 2, 3 order by 1, 3, 2
    loop
        total := total + mc.edit_section(p_dim, g.cx, g.sy, g.cz, g.idxs, g.names);
    end loop;
    return total;
end $$;

create or replace function mc_old.sky_layer(hm smallint[], base int) returns bytea language sql immutable parallel safe as $$
  select decode(string_agg(lpad(to_hex(
           (case when base + (k >> 7) >= hm[2 * (k & 7) + 16 * ((k >> 3) & 15) + 1] then 15 else 0 end)
         | (case when base + (k >> 7) >= hm[2 * (k & 7) + 16 * ((k >> 3) & 15) + 2] then 240 else 0 end)), 2, '0'), '' order by k), 'hex')
  from generate_series(0, 2047) k $$;

create or replace function mc_old.compute_light(p_dim text, p_cx int, p_cz int, p_sky0_as_data boolean default false) returns void language plpgsql volatile as $$
declare
    d          mc.dimension%rowtype;
    hm         smallint[];
    top        int;
    min_sy     int;
    nsec       int;
    last_layer int;
    lay        int;
    base       int;
    lo         int;
    hi         int;
    arr        bytea;
begin
    select * into d from mc.dimension where name = p_dim;
    if not found then raise exception 'unknown dimension %', p_dim; end if;
    select c.hm_world_surface into hm from mc.chunk c where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    if hm is null then raise exception 'chunk %,% of % has no heightmaps; compute them first', p_cx, p_cz, p_dim; end if;
    min_sy := d.min_y >> 4;
    nsec := d.height / 16;
    select max(s.sy) - min_sy into top from mc.chunk_section s
     where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.block_count > 0;
    top := coalesce(top, -1);
    last_layer := least(top + 2, nsec + 1);
    select min(x), max(x) into lo, hi from unnest(hm) x;

    delete from mc.chunk_light where dimension = p_dim and cx = p_cx and cz = p_cz;
    for lay in 0 .. last_layer loop
        if lay = 0 then
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, 0,
                case when p_sky0_as_data then 'data' else 'empty' end, case when p_sky0_as_data then decode(repeat('00', 2048), 'hex') end,
                'empty', null);
            continue;
        end if;
        base := (min_sy + lay - 1) * 16 - d.min_y;            -- y of the layer's lowest block, relative to the world bottom
        if base >= hi then
            arr := decode(repeat('ff', 2048), 'hex');
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, lay, 'data', arr, 'empty', null);
        elsif base + 16 <= lo then
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, lay, 'empty', null, 'empty', null);
        else
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, lay, 'data', mc_old.sky_layer(hm, base), 'empty', null);
        end if;
    end loop;
end $$;

create or replace function mc_old.ensure_chunk_current(p_dim text, p_cx int, p_cz int) returns boolean language plpgsql volatile as $$
declare
    c mc.chunk%rowtype;
    h record;
begin
    select * into c from mc.chunk k where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz for update;
    if not found then return false; end if;
    if not c.dirty and not c.hm_dirty and c.hm_world_surface is not null then return false; end if;
    if c.hm_dirty or c.hm_world_surface is null then
        select * into h from mc.compute_heightmaps(p_dim, p_cx, p_cz);
        update mc.chunk k set hm_motion_blocking = h.motion_blocking, hm_motion_blocking_no_leaves = h.motion_blocking_no_leaves,
                              hm_world_surface = h.world_surface, hm_dirty = false
         where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz;
    end if;
    perform mc_old.compute_light(p_dim, p_cx, p_cz);
    update mc.chunk k set dirty = false where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz;
    return true;
end $$;

create or replace function mc_old.section_wire(s mc.chunk_section) returns bytea language sql stable parallel safe as $$
  select proto.i16(s.block_count) || proto.i16(s.fluid_count)
      || mc.container_wire(s.bits, case when cardinality(s.palette) > 0 then mc.palette_ids(s.palette) end, cardinality(s.palette) = 0, s.data)
      || mc.container_wire(s.biome_bits, case when cardinality(s.biome_palette) > 0 then mc.biome_palette_ids(s.biome_palette) end, cardinality(s.biome_palette) = 0, s.biome_data) $$;

create or replace function mc_old.heightmaps_wire(c mc.chunk, p_height int) returns bytea language sql immutable parallel safe as $$
  select proto.varint(3)
      || proto.varint(4) || proto.varint(octet_length(w1) / 8) || w1
      || proto.varint(5) || proto.varint(octet_length(w2) / 8) || w2
      || proto.varint(1) || proto.varint(octet_length(w3) / 8) || w3
  from (select mc.pack_longs(c.hm_motion_blocking, mc.ceillog2(p_height + 1)) w1,
               mc.pack_longs(c.hm_motion_blocking_no_leaves, mc.ceillog2(p_height + 1)) w2,
               mc.pack_longs(c.hm_world_surface, mc.ceillog2(p_height + 1)) w3) q $$;

create or replace function mc_old.light_wire(p_dim text, p_cx int, p_cz int) returns bytea language sql stable parallel safe as $$
  with l as (select * from mc.chunk_light where dimension = p_dim and cx = p_cx and cz = p_cz)
  select mc.bitset_wire(array(select idx::int from l where sky_kind = 'data' order by idx))
      || mc.bitset_wire(array(select idx::int from l where block_kind = 'data' order by idx))
      || mc.bitset_wire(array(select idx::int from l where sky_kind = 'empty' order by idx))
      || mc.bitset_wire(array(select idx::int from l where block_kind = 'empty' order by idx))
      || proto.varint((select count(*)::int from l where sky_kind = 'data'))
      || coalesce((select string_agg(proto.varint(octet_length(sky)) || sky, ''::bytea order by idx) from l where sky_kind = 'data'), '\x')
      || proto.varint((select count(*)::int from l where block_kind = 'data'))
      || coalesce((select string_agg(proto.varint(octet_length(block)) || block, ''::bytea order by idx) from l where block_kind = 'data'), '\x') $$;

create or replace function mc_old.block_entities_wire(p_dim text, p_cx int, p_cz int) returns bytea language sql stable parallel safe as $$
  select proto.varint(count(*)::int)
      || coalesce(string_agg(proto.i8(((e.x & 15) << 4) | (e.z & 15)) || proto.i16(e.y) || proto.varint(r.protocol_id) || e.nbt, ''::bytea order by e.seq), '\x'::bytea)
  from mc.block_entity e
  join ref.registry r on r.registry = 'minecraft:block_entity_type' and r.name = e.type
  where e.dimension = p_dim and e.cx = p_cx and e.cz = p_cz $$;

create or replace function mc_old.chunk_packet_body(p_dim text, p_cx int, p_cz int) returns bytea language plpgsql stable as $$
declare
    d    mc.dimension%rowtype;
    c    mc.chunk%rowtype;
    secs bytea;
    empty bytea;
begin
    select * into d from mc.dimension where name = p_dim;
    select * into c from mc.chunk where dimension = p_dim and cx = p_cx and cz = p_cz;
    if not found then return null; end if;
    if c.hm_world_surface is null then raise exception 'chunk %,% has no heightmaps; call mc.ensure_chunk_current first', p_cx, p_cz; end if;
    empty := mc.empty_section_wire(p_dim);          -- once, not once per missing section
    select string_agg(case when s.sy is null then empty else mc_old.section_wire(s) end, ''::bytea order by g)
      into secs
      from generate_series(d.min_y >> 4, ((d.min_y + d.height) >> 4) - 1) g
      left join mc.chunk_section s on s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = g;
    return proto.i32(p_cx) || proto.i32(p_cz)
        || mc_old.heightmaps_wire(c, d.height)
        || proto.varint(octet_length(secs)) || secs
        || mc_old.block_entities_wire(p_dim, p_cx, p_cz)
        || mc_old.light_wire(p_dim, p_cx, p_cz);
end $$;

create or replace function mc_old.chunk_packet_build(p_dim text, p_cx int, p_cz int) returns bytea language plpgsql volatile as $$
declare
    v   bigint;
    pkt bytea;
begin
    perform mc_old.ensure_chunk_current(p_dim, p_cx, p_cz);
    select c.version into v from mc.chunk c where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    if not found then return null; end if;
    select k.packet into pkt from mc.chunk_cache k where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz and k.version = v;
    if found then return pkt; end if;
    pkt := proto.frame(mc.chunk_packet_id(), mc_old.chunk_packet_body(p_dim, p_cx, p_cz));
    -- with compression on, the compressed frame is cached with the packet (sql/440): payload = packet id + body = what follows the length VarInt
    insert into mc.chunk_cache (dimension, cx, cz, version, packet, packet_z)
    values (p_dim, p_cx, p_cz, v, pkt, case when mc.compression_enabled() then mc.z_frame(substring(pkt from (select nxt from proto.varint_read(pkt, 0)) + 1)) end)
    on conflict (dimension, cx, cz) do update set version = excluded.version, packet = excluded.packet, packet_z = excluded.packet_z;
    return pkt;
end $$;

create or replace function mc_old.chunk_packet(p_dim text, p_cx int, p_cz int) returns bytea language plpgsql volatile as $$
declare pkt bytea;
begin
    select k.packet into pkt
      from mc.chunk c join mc.chunk_cache k on k.dimension = c.dimension and k.cx = c.cx and k.cz = c.cz and k.version = c.version
     where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz and not c.dirty and not c.hm_dirty and c.hm_world_surface is not null;
    if found then return pkt; end if;
    return mc_old.chunk_packet_build(p_dim, p_cx, p_cz);
end $$;

